const limpia = (v) => String(v === undefined || v === null ? '' : v).replace(/\s+/g, ' ').trim();
return $input.all().map((item, i) => {
  const j = item.json || {};
  const marca = limpia(j.Marca);
  const producto = limpia(j.Producto);
  const gramaje = limpia(j.Gramaje);
  const nombre = [marca, producto, gramaje].filter(Boolean).join(' ');
  return {
    json: Object.assign({}, j, { Marca: marca, Producto: producto, Gramaje: gramaje, nombre: nombre, query: nombre }),
    pairedItem: { item: i },
  };
});

const get = (obj, keys) => {
  for (const k of keys) {
    const v = obj[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  const found = Object.keys(obj).find((k) => keys.some((kk) => kk.toLowerCase() === k.toLowerCase()));
  return found !== undefined && obj[found] !== null ? obj[found] : '';
};

const aPrecio = (v) => {
  if (typeof v === 'number') return v;
  if (v === undefined || v === null || String(v).trim() === '') return '';
  const limpio = String(v).replace(/[^0-9.-]/g, '');
  const n = Number(limpio);
  return limpio !== '' && Number.isFinite(n) ? n : v;
};

// Quita cercados de codigo (tres comillas invertidas) que el modelo a veces agrega
const limpiaTexto = (t) => {
  const fence = String.fromCharCode(96).repeat(3);
  let s = String(t).trim();
  while (s.indexOf(fence) === 0) s = s.slice(fence.length).trim();
  const cierre = s.lastIndexOf(fence);
  if (cierre > 0 && cierre === s.length - fence.length) s = s.slice(0, cierre).trim();
  return s;
};

const esUrl = (u) => typeof u === 'string' && /^https?:\/\//i.test(String(u).trim());

// El Agente devuelve su respuesta en $json.output como texto
const extraerImagen = (res) => {
  if (!res || res.error) return '';
  let salida = res.output;
  if (salida === undefined || salida === null) return '';
  if (typeof salida === 'object') salida = JSON.stringify(salida);
  const texto = limpiaTexto(salida);
  if (!texto) return '';

  const candidatos = [texto];
  const bloque = texto.match(/\{[\s\S]*\}/);
  if (bloque && bloque[0] !== texto) candidatos.push(bloque[0]);

  for (const c of candidatos) {
    try {
      const obj = JSON.parse(c);
      const url = obj.link || obj.image_url || obj.url || obj.imagen || '';
      if (esUrl(url)) return String(url).trim();
    } catch (e) {}
  }

  const mImagen = texto.match(/https?:\/\/[^\s"'<>()]+\.(?:png|jpe?g|webp|gif)(?:\?[^\s"'<>()]*)?/i);
  if (mImagen) return mImagen[0];
  const mUrl = texto.match(/https?:\/\/[^\s"'<>()]+/);
  return mUrl ? mUrl[0] : '';
};

const base = $('Generar Búsqueda de Imagen').all();
const salida = [];

$input.all().forEach((item, i) => {
  const fila = (base[i] && base[i].json) || item.json || {};
  const nombre = String(get(fila, ['nombre']) || '').trim();
  if (!nombre) return;
  salida.push({
    json: {
      nombre: nombre,
      precio: aPrecio(get(fila, ['Precio', 'precio'])),
      categoria: String(get(fila, ['Categoria', 'categoria']) || '').trim(),
      imagen_url: extraerImagen(item.json),
    },
    pairedItem: { item: i },
  });
});

return salida;

const PLACEHOLDER = 'img/logo-alcosto-placeholder.png';
return $input.all().map((item, i) => ({
  json: Object.assign({}, item.json, { imagen_url: PLACEHOLDER }),
  pairedItem: { item: i },
}));

const productos = $input.all().map((item) => item.json);
return [
  {
    json: {
      total: productos.length,
      productos: productos,
      productos_json: JSON.stringify(productos, null, 2),
    },
  },
];
